-- v044 - Integration de l'annuaire national des structures sanitaires
--
-- Source : classeur "Repertoire national des structures sanitaires du Mali
-- (2026)" transmis par l'utilisateur le 12/11/2026 (onglets Hopitaux &
-- Cliniques, Laboratoires & Imagerie, Pharmacies).
--
-- Regles appliquees :
--   * aucune donnee inventee. Tout champ absent de la source reste NULL.
--   * un numero de telephone qui ne tient pas sur 8 chiffres n'est pas
--     "corrige" : il reste vide et le numero publie est reporte dans to_verify.
--   * source_level = 'secondaire' et reliability = 'a_confirmer' : le classeur
--     se declare lui-meme "selection representative", pas un registre officiel.
--   * aucune ligne existante n'est modifiee ni supprimee. On n'insere que les
--     structures absentes de la base (nom normalise, meme region).
--   * aucune structure n'est presentee comme partenaire.
--
-- Retour arriere : voir le bloc ROLLBACK en fin de fichier.

create table if not exists public.import_annuaire_2026 (
  id             bigint generated by default as identity primary key,
  row_type       text not null check (row_type in ('etab','pharmacie')),
  name           text not null,
  kind           text,
  category_label text,
  region_name    text,
  commune_name   text,
  circle_name    text,
  quarter        text,
  ownership      text,
  phone          text,
  phone2         text,
  detail         text,
  note           text,
  imported_at    timestamptz not null default now()
);

alter table public.import_annuaire_2026 enable row level security;
drop policy if exists "admin lit" on public.import_annuaire_2026;
create policy "admin lit" on public.import_annuaire_2026 for select using (public.is_admin());
drop policy if exists "admin ecrit" on public.import_annuaire_2026;
create policy "admin ecrit" on public.import_annuaire_2026 for all using (public.is_admin());

comment on table public.import_annuaire_2026 is
  'Copie fidele du classeur de recensement transmis le 12/11/2026. Conservee pour tracer l''origine de chaque fiche et permettre un retour arriere.';

