-- 1. Etablissements absents de la base
with resolved as (
  select s.*, r.id as region_id, c.id as commune_id, ci.id as circle_id
  from public.import_annuaire_2026 s
  left join public.regions  r  on r.name = s.region_name
  left join public.communes c  on c.name = s.commune_name and c.region_id = r.id
  left join public.circles  ci on ci.name = s.circle_name and ci.region_id = r.id
  where s.row_type = 'etab'
)
insert into public.facility_listings
  (name, kind, category_label, region_id, commune_id, circle_id, quarter,
   ownership, phone, phone2, city_label, source, source_level, source_date,
   reliability, operating_status, contacts_status, is_published, to_verify)
select x.name, x.kind, x.category_label, x.region_id, x.commune_id, x.circle_id,
       x.quarter, x.ownership, x.phone, x.phone2,
       case when x.region_name = 'District de Bamako' then 'Bamako' else x.circle_name end,
       'Repertoire national des structures sanitaires du Mali (2026), classeur transmis a SanteProxi le 12/11/2026', 'secondaire', date '2026-11-12',
       'a_confirmer', 'non_confirme', 'a_confirmer', true,
       left(concat_ws(' ', x.note,
         'Fiche issue d''un classeur de recensement : confirmer adresse, contacts, services et horaires aupres de l''etablissement.'), 500)
from resolved x
where x.region_id is not null
  and not exists (
    select 1 from public.facility_listings f
    where f.region_id = x.region_id
      and public.geo_key(f.name) = public.geo_key(x.name)
  );

-- 2. Services, specialites et examens declares dans la source
insert into public.facility_offers (facility_id, offer_type, code, label, status, source)
select distinct on (f.id, t.otype, t.code) f.id, t.otype, t.code, t.label, 'a_confirmer', 'Repertoire national des structures sanitaires du Mali (2026), classeur transmis a SanteProxi le 12/11/2026'
from (
  select s.name, s.region_name,
         case when s.kind in ('laboratoire','imagerie') then 'examen' else 'specialite' end as otype,
         btrim(item) as label,
         left(regexp_replace(public.normalize_text(btrim(item)), '[^a-z0-9]+', '_', 'g'), 60) as code
  from public.import_annuaire_2026 s
  cross join lateral regexp_split_to_table(coalesce(s.detail, ''), '[,;]') as item
  where s.row_type = 'etab' and length(btrim(item)) between 2 and 160
) t
join public.regions r on r.name = t.region_name
join public.facility_listings f
  on f.region_id = r.id and public.geo_key(f.name) = public.geo_key(t.name)
where t.code ~ '^[a-z0-9_]{2,60}$'
order by f.id, t.otype, t.code
on conflict (facility_id, offer_type, code) do nothing;

-- 3. Officines absentes de la base
with resolved as (
  select s.*, r.id as region_id, c.id as commune_id, ci.name as circle_label
  from public.import_annuaire_2026 s
  left join public.regions  r  on r.name = s.region_name
  left join public.communes c  on c.name = s.commune_name and c.region_id = r.id
  left join public.circles  ci on ci.name = s.circle_name and ci.region_id = r.id
  where s.row_type = 'pharmacie'
)
insert into public.pharmacy_listings
  (name, region_id, commune_id, area_label, address, phone, source, is_published)
select x.name, x.region_id, x.commune_id,
       x.circle_label, x.quarter, x.phone, 'Repertoire national des structures sanitaires du Mali (2026), classeur transmis a SanteProxi le 12/11/2026', true
from resolved x
where x.region_id is not null
  and not exists (
    select 1 from public.pharmacy_listings p
    where p.region_id = x.region_id
      and public.geo_key(p.name) = public.geo_key(x.name)
  );

